#include "pch.h"
#include "PresetPage.xaml.h"
#include "PresetPage.g.cpp"
#include "UIHelpers.h"
namespace winrt::MiniWindow::implementation {
PresetPage::PresetPage(){InitializeComponent();Items().SelectionChanged([this](auto&&,auto&&){if(!syncing_&&!pending_)SelectAsync(Items().SelectedIndex());});NewButton().Click([this](auto&&,auto&&){if(!pending_)SelectAsync(-1);});SaveButton().Click([this](auto&&,auto&&){Save();});ApplyButton().Click([this](auto&&,auto&&){if(!pending_)ActionAsync(false);});DeleteButton().Click([this](auto&&,auto&&){if(!pending_)ActionAsync(true);});}
void PresetPage::Bind(miniwindow::AppCoordinator& app){app_=&app;Refresh();}
bool PresetPage::Dirty(){return std::wstring(PresetName().Text())!=original_;}
void PresetPage::Load(){original_=selected_?app_->Snapshot().state.presets[*selected_].name:L"";PresetName().Text(original_);ApplyButton().IsEnabled(selected_.has_value());DeleteButton().IsEnabled(selected_.has_value());SaveButton().Content(box_value(selected_?L"重命名场景":L"保存当前场景"));Error().Text(L"");if(!selected_){Summary().Text(L"输入名称以保存当前窗口、标签和功能设置。");return;}const auto& p=app_->Snapshot().state.presets[*selected_];Summary().Text(std::to_wstring(p.normalRect.right-p.normalRect.left)+L" × "+std::to_wstring(p.normalRect.bottom-p.normalRect.top)+L" 像素\n"+std::to_wstring(p.tabs.size())+L" 个标签\n"+(p.immersionStyle==miniwindow::ImmersionStyle::Hole?L"鼠标挖孔：":L"移入减淡：")+std::to_wstring(p.immersionStyle==miniwindow::ImmersionStyle::Hole?p.holeOpacityPercent:p.autoHideOpacityPercent)+L"%\n"+p.currentUrl);}
void PresetPage::Refresh(){if(!app_||Dirty())return;syncing_=true;Items().Items().Clear();for(const auto& p:app_->Snapshot().state.presets){auto text=miniwindow::ui::Text(p.name);text.TextTrimming(Microsoft::UI::Xaml::TextTrimming::CharacterEllipsis);text.TextWrapping(Microsoft::UI::Xaml::TextWrapping::NoWrap);Microsoft::UI::Xaml::Controls::ToolTipService::SetToolTip(text,box_value(p.name));Items().Items().Append(text);}Items().Header(Items().Items().Size()?nullptr:box_value(L"暂无预设"));if(selected_&&*selected_>=Items().Items().Size())selected_.reset();Items().SelectedIndex(selected_?static_cast<int>(*selected_):-1);syncing_=false;Load();}
bool PresetPage::Save(){auto result=selected_?app_->RenamePreset(*selected_,std::wstring(PresetName().Text())):app_->SaveCurrentPreset(std::wstring(PresetName().Text()));if(!result.ok){Error().Text(result.message);return false;}if(!selected_)selected_=app_->Snapshot().state.presets.size()-1;original_=std::wstring(PresetName().Text());Refresh();return true;}
Windows::Foundation::IAsyncOperation<bool> PresetPage::CanLeaveAsync(){auto lifetime=get_strong();if(!Dirty())co_return true;Microsoft::UI::Xaml::Controls::ContentDialog dialog;dialog.XamlRoot(XamlRoot());dialog.Title(box_value(L"场景名称尚未保存"));dialog.PrimaryButtonText(L"保存并继续");dialog.SecondaryButtonText(L"放弃修改");dialog.CloseButtonText(L"继续编辑");auto choice=co_await dialog.ShowAsync();if(choice==Microsoft::UI::Xaml::Controls::ContentDialogResult::Primary)co_return Save();if(choice==Microsoft::UI::Xaml::Controls::ContentDialogResult::Secondary){Load();co_return true;}co_return false;}
Windows::Foundation::IAsyncAction PresetPage::SelectAsync(int index){auto lifetime=get_strong();pending_=true;syncing_=true;Items().SelectedIndex(selected_?static_cast<int>(*selected_):-1);syncing_=false;try{if(co_await CanLeaveAsync()){selected_=index>=0?std::optional<size_t>(static_cast<size_t>(index)):std::nullopt;Load();syncing_=true;Items().SelectedIndex(index);syncing_=false;}}catch(const hresult_error& e){Error().Text(e.message());}pending_=false;}
Windows::Foundation::IAsyncAction PresetPage::ActionAsync(bool remove){auto lifetime=get_strong();if(!selected_)co_return;pending_=true;try{if(co_await miniwindow::ui::Confirm(XamlRoot(),remove?L"删除场景？":L"应用场景？",remove?L"仅删除所选预设。":L"当前标签和窗口设置会被替换，网页输入可能丢失。",remove?L"删除":L"应用")){auto result=remove?app_->DeletePreset(*selected_):app_->ApplyPreset(*selected_);if(result.ok){if(remove)selected_.reset();Load();Refresh();}else Error().Text(result.message);}}catch(const hresult_error& e){Error().Text(e.message());}pending_=false;}
}
